import SwiftUI
struct FriendsView:View {@EnvironmentObject var store:AppStore;@State private var following=false;@State private var tailCard:CreatorCard?;@State private var reportCard:CreatorCard?;@State private var reason=""
 var body:some View{ScrollView{VStack(alignment:.leading,spacing:18){Text("Make fight night social.").font(.largeTitle.bold());Picker("Feed",selection:$following){Text("Discover").tag(false);Text("Following").tag(true)}.pickerStyle(.segmented).onChange(of:following){_,value in store.run{try await store.loadFeed(following:value)}};if store.cards.isEmpty{ContentUnavailableView("The first card could be yours",systemImage:"person.2",description:Text("Publish your picks from the poster preview, then share the link."))};ForEach(store.cards){card in VStack(alignment:.leading,spacing:12){HStack{Text("@\(card.username)’s picks").font(.headline);Spacer();Menu{Button("Follow"){store.run{try await store.creatorAction("follows",card.username)}};Button("Unfollow"){store.run{try await store.creatorAction("follows",card.username,remove:true)}};Button("Report"){reportCard=card};Button("Block creator",role:.destructive){store.run{try await store.creatorAction("blocks",card.username)}}}label:{Image(systemName:"ellipsis")}};Text(card.eventName).font(.title3.bold());ForEach(card.picks,id:\.fightId){p in HStack{Image(systemName:p.lock ? "lock.fill":"figure.boxing").foregroundStyle(p.lock ? .yellow:Color.accentColor);VStack(alignment:.leading){Text(p.fighter ?? "Fighter").font(.subheadline.bold());Text((p.method ?? "To win")+(p.round.map{" · Round \($0)"} ?? "")).font(.caption).foregroundStyle(.secondary)}}};Text(card.verifiedEligible==true ? "Published before the verification cutoff":"Casual picks · excluded from verified record").font(.caption2).foregroundStyle(.secondary);HStack{Button("Tail picks"){tailCard=card}.buttonStyle(.borderedProminent);ShareLink("Share",item:URL(string:APIClient.base.absoluteString+"/?betaShare="+card.id)!)}}.padding().background(.white.opacity(0.05),in:RoundedRectangle(cornerRadius:16))};if store.feedNext != nil{Button("More cards"){store.run{try await store.loadFeed(following:following,more:true)}}}}.padding()}.navigationTitle("Friends").task{store.run{try await store.loadFeed(following:following)}}.refreshable{store.run{try await store.loadFeed(following:following)}}.confirmationDialog("Tail this card? Replace & tail will replace your saved picks for this event.",isPresented:Binding(get:{tailCard != nil},set:{if !$0{tailCard=nil}}),titleVisibility:.visible){if let card=tailCard{Button("Tail without replacing"){store.run{try await store.tail(card,replace:false)}};Button("Replace & tail",role:.destructive){store.run{try await store.tail(card,replace:true)}}}}.alert("Report this card",isPresented:Binding(get:{reportCard != nil},set:{if !$0{reportCard=nil}})){TextField("What’s the problem?",text:$reason);Button("Send report"){if let card=reportCard{store.run{try await store.report(card,reason:reason)}}};Button("Cancel",role:.cancel){}}}
